-- Read-only baseline extracted from TESTE on 2026-08-13.
-- Source: Resultado_da_Query (24).xlsx; do not edit as deployment source.
CREATE OR REPLACE function         FNC_ESTCOMERCIAL_PRA(P_CODPROD TGFPRO.CODPROD%TYPE)
RETURN FLOAT is
ESTCOMERCIAL TGFEST.ESTOQUE%TYPE;


BEGIN

BEGIN

SELECT
SUM(
NVL(EST.ESTOQUE,0)
- NVL(EST.RESERVADO,0)
)
INTO ESTCOMERCIAL
FROM TGFEST EST
JOIN TGFLOC LOC ON EST.CODLOCAL = LOC.CODLOCAL
WHERE EST.CODPROD = P_CODPROD
AND EST.CODLOCAL = '1000000'
AND EST.TIPO = 'P'
AND EST.CODPARC = 0
AND EST.ATIVO = 'S'
AND NVL(LOC.AD_ESTCOM,'N') = 'S';


END;

RETURN(NVL(ESTCOMERCIAL,0));
END FNC_ESTCOMERCIAL_PRA;
/
